using System.Security.Cryptography;using Microsoft.AspNetCore.Cryptography.KeyDerivation;
namespace Dentiva.Infrastructure.Services;public sealed class PasswordService{public string Hash(string password){var salt=RandomNumberGenerator.GetBytes(16);var key=KeyDerivation.Pbkdf2(password,salt,KeyDerivationPrf.HMACSHA512,120_000,32);return $"{Convert.ToBase64String(salt)}.{Convert.ToBase64String(key)}";}public bool Verify(string password,string encoded){var p=encoded.Split('.');if(p.Length!=2)return false;var key=KeyDerivation.Pbkdf2(password,Convert.FromBase64String(p[0]),KeyDerivationPrf.HMACSHA512,120_000,32);return CryptographicOperations.FixedTimeEquals(key,Convert.FromBase64String(p[1]));}}
